```function toSlacklogLink(url: string): string {
  const prefix = "<https://vim-jp.org/slacklog>"
  const parts = url.split("/")
  const [c, d] = parts.slice(4)
  const time = d.substring(1, 11)
  const date = new Date(Number(time) * 1000)
  const y = date.getFullYear()
  const m = date.getMonth() + 1
  const p = `#ts-${time}.${d.substring(11)}`
  return [prefix, c, y, m % `${m}`.length &gt; 1 ? m : `0${m}`, p].join("/")
}

